-- Catalogue de postes de guet du mercenaire chasseur -- lot 4 de
-- docs/CONCEPTION-mercenaire-chasseur.md (depot coa-project).
--
-- NE PAS EDITER A LA MAIN. Ce fichier est ENGENDRE par
--   python3 outils/engendrer-postes-guet.py --ecrire
-- qui croise les hubs de TravelMgr, game_graveyard, le graphe
-- playerbots_travelnode/_link et quest_poi, et ECARTE tout point en lieu
-- sans PvP au sens de PlayerbotAIConfig::CoaLieuSansPvp (sanctuaire sur
-- l'AIRE, capitale sur la ZONE, puis les listes de conf).
--
-- 2264 postes retenus ; 337 candidats ecartes pour lieu sans PvP,
-- 32 pour zone tenue par un Battlefield (le bot y serait invite a la
-- bataille, puis TELEPORTE dehors quand l'invitation expire : voir
-- charger_zones_battlefield dans le generateur).
-- Cartes : 0, 1, 530, 571 (AiPlayerbot.RandomBotMaps).
--
-- RE-APPLICABLE par construction : DROP TABLE IF EXISTS, puis CREATE, puis
-- INSERT. Le schema est donc TOUJOURS celui de ce fichier, quel qu'ait ete
-- le precedent.
--
-- POURQUOI PAS « CREATE TABLE IF NOT EXISTS » + « DELETE », qui etait la
-- premiere forme. Ce contrat-la ne tenait que tant que le schema ne bougeait
-- pas : sur une table deja presente le CREATE est un no-op, tandis que le
-- DELETE et les INSERT, eux, s'executent. Une regeneration qui ajoute ou
-- renomme une colonne VIDAIT donc la table -- DELETE reussi, INSERT en
-- ERROR 1054 Unknown column -- et le chargeur C++ (Ai/Coa/CoaPostes.h,
-- Charger) lit ce vide comme un etat annonce : il trouve la table dans
-- information_schema, la requete WHERE actif = 1 ne rend rien, et tous les
-- bots retombent en silence sur le comportement du lot 2, sans que rien ne
-- distingue cet echec d'un serveur qui n'a jamais joue ce fichier.
--
-- LA TABLE EST ENGENDREE ET LUE SEULE : personne d'autre n'y ecrit, la
-- detruire ne detruit donc aucun etat d'exploitation. Seule la colonne
-- `actif`, qu'un exploitant peut mettre a 0, est perdue par un DROP -- et
-- elle l'etait deja par le DELETE.
--
-- ATTENTION : le serveur en service a Updates.EnableDatabases = 0
-- (worldserver.conf). Ce fichier n'est donc PAS applique tout seul au
-- demarrage ; il s'applique a la main :
--   mysql acore_world < modules/mod-playerbots/data/sql/world/custom/playerbots_coa_postes_guet.sql
--
-- faction : DROIT DE TIRAGE, pas la faction de la source -- 0 les deux camps,
--           1 Alliance seule, 2 Horde seule. La fusion est gloutonne PAR CAMP
--           (voir fusionner dans le generateur) : un poste neutre retenu par
--           un seul camp sort avec le numero de ce camp, parce que l'autre a
--           un poste mieux pese a moins de 50 yd.
-- source  : classe du poste -- auberge, volerie, cimetiere, route. LUE par le
--           chargeur : c'est elle qui porte le budget de classe du tirage.
-- poids   : poids DANS SA CLASSE. Il part de l'enrichissement mesure x 10
--           (section 2.1 du dossier) -- auberge 180, volerie 90, cimetiere 34,
--           route 10 -- module par la densite de points de quete, d'un facteur
--           x1,25 par tranche de dix points a moins de 75 yd, deux tranches au
--           plus. ENTRE CLASSES il ne se compare pas : le tirage repartit un
--           budget par classe (Ai/Coa/CoaPostes.h), sans quoi le NOMBRE de
--           carrefours ecraserait le FACTEUR des auberges.
-- actif   : 0 retire le poste du tirage sans le supprimer.

DROP TABLE IF EXISTS `playerbots_coa_poste_guet`;

CREATE TABLE `playerbots_coa_poste_guet` (
  `id`        INT UNSIGNED      NOT NULL,
  `map`       SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  `x`         FLOAT             NOT NULL DEFAULT 0,
  `y`         FLOAT             NOT NULL DEFAULT 0,
  `z`         FLOAT             NOT NULL DEFAULT 0,
  `zoneId`    SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  `areaId`    SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  `palierMin` TINYINT UNSIGNED  NOT NULL DEFAULT 1,
  `palierMax` TINYINT UNSIGNED  NOT NULL DEFAULT 80,
  `faction`   TINYINT UNSIGNED  NOT NULL DEFAULT 0,
  `poids`     SMALLINT UNSIGNED NOT NULL DEFAULT 1,
  `actif`     TINYINT UNSIGNED  NOT NULL DEFAULT 1,
  `source`    VARCHAR(16)       NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `idx_carte_palier` (`map`, `palierMin`, `palierMax`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;













